#include "test.hpp"
#include "worldgen/chemistry.hpp"
#include "worldgen/planetary_physics.hpp"
#include <cmath>
WG_TEST(common_planetary_phases_are_distinguished){using namespace worldgen;ChemicalDatabase db;const auto*w=db.find("H2O");WG_CHECK(w!=nullptr);WG_CHECK(phase_at(*w,288.0,101325.0)==Phase::liquid);const auto*m=db.find("CH4");WG_CHECK(m!=nullptr);WG_CHECK(phase_at(*m,94.0,150000.0)==Phase::liquid);const auto*c=db.find("CO2");WG_CHECK(c!=nullptr);WG_CHECK(phase_at(*c,210.0,101325.0)==Phase::gas);}
WG_TEST(titan_like_atmosphere_produces_photochemistry){using namespace worldgen;AtmosphereComposition a;a.surface_pressure_pa=150000;a.mole_fraction={{"N2",0.95},{"CH4",0.05}};const auto products=photochemistry_products(a,0.08);bool tholin=false;for(const auto&p:products)tholin|=p.product=="tholins";WG_CHECK(tholin);}
WG_TEST(dynamic_liquid_level_conserves_integrated_volume){using namespace worldgen;ChemicalDatabase db;SphereGrid grid(16,8,2574.7);RasterF z(8,16),t(8,16,94.0f);for(std::size_t i=0;i<z.size();++i)z.span()[i]=static_cast<float>(-3.0+6.0*static_cast<double>(i)/static_cast<double>(z.size()-1));const std::vector<VolatileInventory>inv{{"CH4",2e18},{"C2H6",5e17}};const auto v=solve_volatile_cycle(db,grid,z,t,150000,1.35,inv,0.2);double integrated=0;const double sphere=4.0*kPi*std::pow(grid.radius_km()*1000.0,2);for(std::size_t y=0;y<grid.height();++y)for(std::size_t x=0;x<grid.width();++x)integrated+=static_cast<double>(v.surface_liquid.depth_m(y,x))*sphere*grid.area_weight(y);WG_NEAR(integrated,v.surface_liquid.volume_m3,std::max(1.0,v.surface_liquid.volume_m3*2e-5));}
WG_TEST(moon_of_giant_computes_tidal_heating_and_regime){using namespace worldgen;WorldOrbit orbit;orbit.is_moon=true;orbit.host_mass_earth=95.16;orbit.host_semimajor_axis_km=1221870;orbit.host_eccentricity=0.0288;const auto heat=tidal_heating(orbit,0.0225,2574.7);WG_CHECK(heat.host_surface_flux_w_m2>=0);VolatileCycleResult vol;vol.species.push_back({"H2O",0,1e20,0,1000,0,0,1});const auto regime=classify_geodynamics(0.0225,0.404,4.5,94.0,heat.host_surface_flux_w_m2,vol);WG_CHECK(!geodynamic_regime_name(regime.regime).empty());}
